gravuru-variante-m.liquid.value:
{%- comment -%}
  Variante M (AOSU-Upgrade-Konfigurator) – Laufzeit aus der Theme-App-Extension statt aus dem
  unveröffentlichten Theme /t/40/. Rendert nur auf Produktseiten, deren Beschreibung den
  Konfigurator-Host enthält. Die Produktbeschreibung selbst enthält keine <script>/<style> mehr
  (siehe produktbeschreibung-variante-m-bereinigt.html); der Launcher lädt Editor, Profil und
  Admin-Runtime relativ zu seinem eigenen Asset-Pfad nach.
{%- endcomment -%}
{%- if request.page_type == 'product' and product != blank -%}
  {%- assign gv_desc = product.description | default: '' -%}
  {%- if gv_desc contains 'gravuru-funkklingel-product' or gv_desc contains 'gravuru-model-product' -%}
    <link rel="stylesheet" href="{{ 'gravuru-variante-m-pdp.css' | asset_url }}">
    <script src="{{ 'gravuru-variante-m-pdp.js' | asset_url }}" defer></script>
    <script src="{{ 'gravuru-model-launcher-live-v5.js' | asset_url }}" defer></script>
    {{ 'gravuru-model-editor-live.js' | asset_url | preload_tag: as: 'script' }}
  {%- endif -%}
{%- endif -%}

personalizer.liquid.value:
{% if request.page_type == 'product' %}
  {% assign editor_url = product.metafields.gravuru_workbench.preview_url.value %}
  {% assign source_id = product.metafields.gravuru_workbench.source_id.value %}
  {% assign manifest = product.metafields.gravuru_workbench.manifest.value %}
  {% if editor_url != blank or source_id != blank %}
    <div data-gravuru-m hidden>
      <script type="application/json" data-gravuru-binding>
        {"productId":{{ product.id | append: '' | json }},"ready":{% if manifest.customerEnabled and editor_url != blank %}true{% else %}false{% endif %},"url":{{ editor_url | json }},"variants":[{% for variant in product.variants %}{{ variant.id | append: '' | json }}{% unless forloop.last %},{% endunless %}{% endfor %}]}
      </script>
      {% if manifest.customerEnabled and editor_url != blank %}
        <button type="button">Jetzt personalisieren</button>
        <p role="status">Design auswählen, Text gestalten und eigenes Foto hochladen.</p>
      {% else %}
        <button type="button" disabled>Konfigurator wird vorbereitet …</button>
        <p role="status">Die Produktübertragung läuft noch. Der Konfigurator erscheint hier automatisch, sobald er bereit ist.</p>
      {% endif %}
    </div>
    <script src="{{ 'gravuru-readiness.js' | asset_url }}" defer></script>
    <script src="{{ 'gravuru-personalizer.js' | asset_url }}" defer></script>
  {% endif %}
{% endif %}
{%- render 'gravuru-variante-m' -%}
{% schema %}
{"name":"Gravuru Personalisieren","target":"body","settings":[]}
{% endschema %}

configurator.liquid.value:
{% assign configuration = product.metafields.gravuru.configurator.value %}
{% if product != blank and configuration.enabled == true %}
  <div {{ block.shopify_attributes }}>
    <gravuru-configurator data-engine-src="{{ 'gravuru-engine.js' | asset_url }}">
      <script type="application/json" data-configuration>
        {
          "demo": false,
          "productId": {{ product.id | prepend: 'gid://shopify/Product/' | json }},
          "productHandle": {{ product.handle | json | replace: '<', '\u003c' }},
          "assignment": {{ configuration | json | replace: '<', '\u003c' }},
          "catalogUrl": {{ 'gravuru-catalog.json' | asset_url | json }},
          "materialUrl": {{ 'gravuru-stainless-fine.png' | asset_url | json }},
          "cartAddUrl": {{ routes.cart_add_url | json }},
          "title": {{ block.settings.heading | default: product.title | json | replace: '<', '\u003c' }},
          "hero": {% if product.featured_image %}{{ product.featured_image | image_url: width: 1200 | json | replace: '<', '\u003c' }}{% else %}null{% endif %},
          "width": {{ configuration.widthMm | json }},
          "height": {{ configuration.heightMm | json }},
          "orderEnabled": false,
          "variant": {{ product.selected_or_first_available_variant.id | append: '' | json }},
          "variants": [
            {% for variant in product.variants limit: 250 %}
              {"id":{{ variant.id | append: '' | json }},"sku":{{ variant.sku | json | replace: '<', '\u003c' }},"title":{{ variant.title | json | replace: '<', '\u003c' }},"available":{{ variant.available | json }},"priceLabel":{{ variant.price | money_with_currency | strip_html | json | replace: '<', '\u003c' }}}
              {% unless forloop.last %},{% endunless %}
            {% endfor %}
          ],
          "labels": {}
        }
      </script>
      <noscript>{{ 'configurator.enable_js' | t }}</noscript>
    </gravuru-configurator>
  </div>
{% elsif request.design_mode %}
  <div {{ block.shopify_attributes }}>{{ 'configurator.assignment_needed' | t }}</div>
{% endif %}
{% schema %}
{
  "name": "Produktkonfigurator",
  "target": "section",
  "enabled_on": {"templates":["product"]},
  "javascript": "gravuru-loader.js",
  "settings": [{"type":"text","id":"heading","label":"Überschrift","default":"Dein Schild gestalten"}]
}
{% endschema %}

targets.input_query:
query CartTransformRunInput {
  presentmentCurrencyRate
  cart {
    lines {
      id
      motifs: attribute(key: "_gravuru_motifs") { value }
      uploads: attribute(key: "_gravuru_uploads") { value }
      revision: attribute(key: "_gravuru_revision") { value }
      designFile: attribute(key: "Bearbeitbarer Entwurf") { value }
      merchandise { __typename ... on ProductVariant { id product { id pricing: metafield(namespace: "$app", key: "personalization") { jsonValue } } } }
    }
  }
}

